{
  "id": 17,
  "knowledge": "Cabin Habitability Standard",
  "description": "Defines the minimum standards for habitable cabin conditions in polar environments.",
  "definition": "A cabin meets 'Habitability Standards' when it maintains internal temperature (cabinclimate.temperature_c) between 18-24\u00b0C, oxygen levels (cabinclimate.o2_percent) above 19.5%, CO2 levels (cabinclimate.co2_ppm) below 1000 ppm, functioning ventilation systems, and operational heating systems."
}

{
  "id": 20,
  "knowledge": "reliabilityindex",
  "description": "Illustrates the significance of reliability index measurements in equipment durability.",
  "definition": "The reliability index typically ranges from 0 to 1, where values below 0.5 indicate equipment that fails frequently and requires constant maintenance, values between 0.5-0.8 represent equipment with occasional failures that require regular maintenance, and values above 0.8 indicate highly reliable equipment with minimal downtime."
}

{
  "id": 0,
  "knowledge": "Equipment Efficiency Rating (EER)",
  "description": "A composite metric that evaluates the overall efficiency of equipment based on performance, reliability, and environmental impact.",
  "definition": "EER = \\frac{performanceindex + reliabilityindex}{2} \\times (1 - \\frac{environmentalimpactindex}{10}), \\text{ where higher values indicate more efficient equipment with better performance and lower environmental impact.}"
}

